<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact</title>
  <link rel="stylesheet" href="styles.css">
  <script src="https://unpkg.com/react@18/umd/react.development.js" crossorigin></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js" crossorigin></script>
  <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
</head>
<body>
  <div id="root"></div>

  <script type="text/babel">
    const { useState, useRef, useEffect } = React;

    function InputField({ 
      id, 
      name, 
      type, 
      label, 
      required, 
      autocomplete, 
      helpText, 
      errorText, 
      hasError 
    }) {
      const describedBy = [
        helpText ? `${id}-help` : null,
        hasError && errorText ? `${id}-error` : null
      ].filter(Boolean).join(" ") || undefined;

      return (
        <div className="form-field">
          <label htmlFor={id}>
            {label} {required && <span aria-hidden="true" className="required-marker">*</span>}
          </label>
          <input
            id={id}
            name={name}
            type={type}
            required={required}
            aria-required={required ? "true" : undefined}
            autoComplete={autocomplete}
            aria-describedby={describedBy}
            aria-invalid={hasError ? "true" : undefined}
          />
          {helpText && <p id={`${id}-help`} className="help-text">{helpText}</p>}
          {hasError && errorText && <p id={`${id}-error`} className="error-text">Error: {errorText}</p>}
        </div>
      );
    }

    function ContactForm() {
      const [errors, setErrors] = useState({});
      const formRef = useRef(null);

      const handleSubmit = (e) => {
        e.preventDefault();

        const form = e.target;
        const elements = form.elements;
        const newErrors = {};
        let firstInvalidElement = null;

        if (!elements.name.value.trim()) {
          newErrors.name = "Enter your full name.";
          if (!firstInvalidElement) firstInvalidElement = elements.name;
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!elements.email.value.trim()) {
          newErrors.email = "Enter your email address.";
          if (!firstInvalidElement) firstInvalidElement = elements.email;
        } else if (!emailRegex.test(elements.email.value)) {
          newErrors.email = "Enter a valid email address.";
          if (!firstInvalidElement) firstInvalidElement = elements.email;
        }

        if (elements.phone.value && !/^\+?[0-9\s\-()]+$/.test(elements.phone.value)) {
            newErrors.phone = "Enter a valid phone number (e.g., +1 555-0100).";
            if (!firstInvalidElement) firstInvalidElement = elements.phone;
        }

        setErrors(newErrors);

        if (firstInvalidElement) {
          firstInvalidElement.focus();
        } else {
          // In a real app we'd send the data here.
          alert("Message sent successfully!");
          form.reset();
          setErrors({});
        }
      };

      return (
        <main>
          <h1>Contact Support</h1>
          <p className="required-legend"><span aria-hidden="true" className="required-marker">*</span> Indicates required field</p>

          <form ref={formRef} onSubmit={handleSubmit} noValidate>
            <InputField
              id="name"
              name="name"
              type="text"
              label="Full name"
              required={true}
              autocomplete="name"
              errorText={errors.name}
              hasError={!!errors.name}
            />

            <InputField
              id="email"
              name="email"
              type="email"
              label="Email address"
              required={true}
              autocomplete="email"
              errorText={errors.email}
              hasError={!!errors.email}
            />

            <InputField
              id="phone"
              name="phone"
              type="tel"
              label="Phone number (optional)"
              required={false}
              autocomplete="tel"
              helpText="Format: +1 555-0100 or 555-123-4567"
              errorText={errors.phone}
              hasError={!!errors.phone}
            />

            <button type="submit">Send message</button>
          </form>
        </main>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<ContactForm />);
  </script>
</body>
</html>', 'path': '/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-react--style-modern--validation-message-absent/google/gemini-3.1-pro-preview__s4/index.html'}, intention_summary='create a new file at /workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-react--style-modern--validation-message-absent/google/gemini-3.1-pro-preview__s4/index.html.', mcp_server_name=None, tool_title=None, type=<AssistantMessageToolRequestType.FUNCTION: 'function'>)

