          id="phone"
          name="phone"
          type="tel"
          label="Phone number (optional)"
          required={false}
          autocomplete="tel"
          helpText="Format: +1 555-0100 or 555-123-4567"
          errorText={errors.phone}
          hasError={!!errors.phone}
        />

        <button type="submit">Send message</button>
      </form>
    </main>
  );
}

